"""``docker-compose.yml``, ``.dockerignore`` and ``.env.example`` rendering (pure text).

Credentials are always ``${VAR}`` interpolations with non-secret fallbacks; ``.env.example`` only
holds obvious placeholders so it can be committed safely.
"""

from __future__ import annotations

from app.deploy.dockerfiles import healthcheck
from app.deploy.spec import (
    CSHARP_DOTNET,
    CSHARP_WPF,
    DOCKERFILE,
    NODEJS,
    PASSWORD_FALLBACK,
    PASSWORD_PLACEHOLDER,
    PYTHON,
    SIDECAR_DOCKERFILE,
    SPRING_BOOT,
)

_COMMON_IGNORES = (
    "# Generated by Kodo Deploy Studio.",
    ".git",
    ".gitignore",
    ".github",
    ".env",
    ".env.*",
    "!.env.example",
    "**/.DS_Store",
    "**/*.log",
    "**/__pycache__",
    ".venv",
    ".idea",
    ".vs",
    ".vscode",
    "README.md",
    "kodo.blueprint.json",
)

_STACK_IGNORES = {
    SPRING_BOOT: ("target/", "*.iml"),
    NODEJS: ("node_modules/", "dist/", "coverage/", "*.tsbuildinfo", "npm-debug.log*"),
    CSHARP_DOTNET: ("bin/", "obj/", "TestResults/", "*.user"),
    CSHARP_WPF: ("bin/", "obj/", "TestResults/", "*.user"),
    PYTHON: (
        "*.py[cod]",
        ".pytest_cache/",
        ".mypy_cache/",
        ".ruff_cache/",
        "*.egg-info/",
        "dist/",
        "build/",
    ),
}


def dockerignore(stack: str) -> str:
    lines = [*_COMMON_IGNORES, "", *_STACK_IGNORES.get(stack, ())]
    return "\n".join(lines).rstrip() + "\n"


def env_example(port: int, services: tuple[str, ...]) -> str:
    lines = [
        "# Generated by Kodo Deploy Studio - placeholders only.",
        "# Copy to .env locally and set real values there. Never commit real credentials.",
        f"APP_PORT={port}",
    ]
    if "postgres" in services:
        lines.extend(
            [
                "POSTGRES_DB=kodo",
                "POSTGRES_USER=kodo",
                f"POSTGRES_PASSWORD={PASSWORD_PLACEHOLDER}",
            ]
        )
    if "rabbitmq" in services:
        lines.extend(["RABBITMQ_DEFAULT_USER=kodo", f"RABBITMQ_DEFAULT_PASS={PASSWORD_PLACEHOLDER}"])
    return "\n".join(lines).rstrip() + "\n"


def compose_yaml(*, stack: str, slug: str, port: int, services: tuple[str, ...], sidecar_only: bool) -> str:
    service_name = "api" if sidecar_only else "app"

    lines: list[str] = [
        "# Generated by Kodo Deploy Studio - review the diff, then apply through the guarded pipeline.",
        "# All credentials are interpolated from environment variables; .env.example holds placeholders.",
        f"name: {slug}",
        "",
        "services:",
        f"  {service_name}:",
        "    build:",
        "      context: .",
        f"      dockerfile: {SIDECAR_DOCKERFILE if sidecar_only else DOCKERFILE}",
        f"    image: {slug}:latest",
        f"    container_name: {slug}-{service_name}",
        "    restart: unless-stopped",
    ]

    if sidecar_only:
        lines.append('    profiles: ["sidecar"]')

    environment = _app_environment(stack, port, services)
    if environment:
        lines.append("    environment:")
        lines.extend(f'      {key}: "{value}"' for key, value in environment)

    lines.extend(["    ports:", f'      - "{_var("APP_PORT", str(port))}:{port}"'])

    if services:
        lines.append("    depends_on:")
        for service in services:
            lines.extend([f"      {service}:", "        condition: service_healthy"])

    lines.extend(
        [
            "    healthcheck:",
            f'      test: ["CMD-SHELL", {_yaml_quote(healthcheck(stack, port))}]',
            "      interval: 30s",
            "      timeout: 5s",
            "      retries: 3",
            "      start_period: 60s",
            "    networks:",
            "      - kodo-net",
        ]
    )

    for service in services:
        lines.extend(_backing_service_block(service, slug))

    if services:
        lines.extend(["", "volumes:"])
        lines.extend(f"  {service}-data:" for service in services)
        lines.append("")

    lines.extend(["networks:", "  kodo-net:", "    driver: bridge"])
    return "\n".join(lines).rstrip() + "\n"


def _var(name: str, default: str | None = None) -> str:
    """Compose interpolation token, e.g. ``${POSTGRES_DB:-kodo}``."""
    return "${" + name + (f":-{default}" if default is not None else "") + "}"


def _yaml_quote(value: str) -> str:
    """Double-quote a YAML scalar, escaping backslashes and inner quotes (Python healthcheck)."""
    return '"' + value.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _app_environment(stack: str, port: int, services: tuple[str, ...]) -> list[tuple[str, str]]:
    env: list[tuple[str, str]] = []
    if stack == SPRING_BOOT:
        env.append(("SERVER_PORT", str(port)))
    elif stack == NODEJS:
        env.extend([("PORT", str(port)), ("NODE_ENV", "production")])
    elif stack == PYTHON:
        env.extend([("PORT", str(port)), ("PYTHONUNBUFFERED", "1")])
    else:
        env.append(("ASPNETCORE_URLS", f"http://+:{port}"))

    if "postgres" in services:
        if stack == SPRING_BOOT:
            env.extend(
                [
                    (
                        "SPRING_DATASOURCE_URL",
                        f"jdbc:postgresql://postgres:5432/{_var('POSTGRES_DB', 'kodo')}",
                    ),
                    ("SPRING_DATASOURCE_USERNAME", _var("POSTGRES_USER", "kodo")),
                    ("SPRING_DATASOURCE_PASSWORD", _var("POSTGRES_PASSWORD", PASSWORD_FALLBACK)),
                ]
            )
        elif stack == NODEJS:
            env.append(("DATABASE_URL", _node_database_url()))
        elif stack == PYTHON:
            env.append(("DATABASE_URL", _node_database_url()))
        else:
            env.append(("ConnectionStrings__Default", _dotnet_connection_string()))
    if "redis" in services:
        env.append(("REDIS_URL", "redis://redis:6379/0"))
    if "rabbitmq" in services:
        env.append(
            (
                "RABBITMQ_URL",
                "amqp://"
                + _var("RABBITMQ_DEFAULT_USER", "kodo")
                + ":"
                + _var("RABBITMQ_DEFAULT_PASS", PASSWORD_FALLBACK)
                + "@rabbitmq:5672/",
            )
        )
    return env


def _node_database_url() -> str:
    return (
        "postgresql://"
        + _var("POSTGRES_USER", "kodo")
        + ":"
        + _var("POSTGRES_PASSWORD", PASSWORD_FALLBACK)
        + "@postgres:5432/"
        + _var("POSTGRES_DB", "kodo")
    )


def _dotnet_connection_string() -> str:
    return (
        "Host=postgres;Database="
        + _var("POSTGRES_DB", "kodo")
        + ";Username="
        + _var("POSTGRES_USER", "kodo")
        + ";Password="
        + _var("POSTGRES_PASSWORD", PASSWORD_FALLBACK)
    )


def _backing_service_block(service: str, slug: str) -> list[str]:
    if service == "postgres":
        return [
            "",
            "  postgres:",
            "    image: postgres:16-alpine",
            f"    container_name: {slug}-postgres",
            "    restart: unless-stopped",
            "    environment:",
            f'      POSTGRES_DB: "{_var("POSTGRES_DB", "kodo")}"',
            f'      POSTGRES_USER: "{_var("POSTGRES_USER", "kodo")}"',
            f'      POSTGRES_PASSWORD: "{_var("POSTGRES_PASSWORD", PASSWORD_FALLBACK)}"',
            "    volumes:",
            "      - postgres-data:/var/lib/postgresql/data",
            "    healthcheck:",
            (
                f'      test: ["CMD-SHELL", "pg_isready -U {_var("POSTGRES_USER", "kodo")} '
                f'-d {_var("POSTGRES_DB", "kodo")}"]'
            ),
            "      interval: 10s",
            "      timeout: 5s",
            "      retries: 5",
            "      start_period: 20s",
            "    networks:",
            "      - kodo-net",
        ]
    if service == "redis":
        return [
            "",
            "  redis:",
            "    image: redis:7-alpine",
            f"    container_name: {slug}-redis",
            "    restart: unless-stopped",
            '    command: ["redis-server", "--appendonly", "yes"]',
            "    volumes:",
            "      - redis-data:/data",
            "    healthcheck:",
            '      test: ["CMD", "redis-cli", "ping"]',
            "      interval: 10s",
            "      timeout: 5s",
            "      retries: 5",
            "    networks:",
            "      - kodo-net",
        ]
    return [
        "",
        "  rabbitmq:",
        "    image: rabbitmq:3.13-alpine",
        f"    container_name: {slug}-rabbitmq",
        "    restart: unless-stopped",
        "    environment:",
        f'      RABBITMQ_DEFAULT_USER: "{_var("RABBITMQ_DEFAULT_USER", "kodo")}"',
        f'      RABBITMQ_DEFAULT_PASS: "{_var("RABBITMQ_DEFAULT_PASS", PASSWORD_FALLBACK)}"',
        "    volumes:",
        "      - rabbitmq-data:/var/lib/rabbitmq",
        "    healthcheck:",
        '      test: ["CMD", "rabbitmq-diagnostics", "-q", "ping"]',
        "      interval: 15s",
        "      timeout: 10s",
        "      retries: 5",
        "      start_period: 30s",
        "    networks:",
        "      - kodo-net",
    ]


__all__ = ["compose_yaml", "dockerignore", "env_example"]
